validations:
validation {
    condition     = alltrue([for folder in values(var.rm_folders) : length(folder.name) >= 1 && length(folder.name) <= 40])
    error_message = "Every rm_folders[*].name must be between 1 and 40 characters, as required by the STACKIT Resource Manager API."
  }

validation {
    condition     = var.connectivity == null || var.connectivity.network_area == null || var.connectivity.network_areas == null
    error_message = "Set either connectivity.network_area or connectivity.network_areas, not both."
  }

validation {
    condition     = var.connectivity == null || var.connectivity.firewall == null || var.connectivity.firewalls == null
    error_message = "Set either connectivity.firewall or connectivity.firewalls, not both."
  }

validation {
    condition     = var.connectivity == null || var.connectivity.firewalls == null || var.connectivity.network_areas == null || (length(setsubtract(toset(keys(var.connectivity.firewalls)), toset(keys(var.connectivity.network_areas)))) == 0 && length(setsubtract(toset(keys(var.connectivity.network_areas)), toset(keys(var.connectivity.firewalls)))) == 0)
    error_message = "connectivity.firewalls keys must exactly match connectivity.network_areas keys."
  }

validation {
    condition     = var.connectivity_regions == null || length(setsubtract(toset(keys(var.connectivity_regions)), toset(["eu01", "eu02"]))) == 0
    error_message = "connectivity_regions supports only eu01 and eu02. Add a static provider alias and module instance before using another region."
  }

validation {
    condition     = var.firewall_config == null || try(var.connectivity.firewall, null) != null
    error_message = "firewall_config requires connectivity.firewall to be set, there is no appliance to push a policy to otherwise."
  }

validation {
    condition = var.firewall_config == null || alltrue([
      for p in values(var.firewall_config.port_forwards) : p.source_net != "any" || !p.enabled
    ])
    error_message = "port_forwards[*].source_net must be narrowed from \"any\", or the entry disabled. An unrestricted forward exposes the target to the whole internet."
  }

validation {
    condition = alltrue([
      for landing_zone in values(var.landing_zones) : (
        var.connectivity_regions == null || (
          landing_zone.region != null && contains(keys(var.connectivity_regions), landing_zone.region)
        )
        ) && (
        !landing_zone.corporate || (
          var.connectivity_regions != null
          ? contains(keys(try(var.connectivity_regions[landing_zone.region].network_areas, {})), landing_zone.network_area_key)
          : var.connectivity != null && (
            var.connectivity.network_areas != null
            ? contains(keys(var.connectivity.network_areas), landing_zone.network_area_key)
            : var.connectivity.network_area != null && landing_zone.network_area_key == "default"
          )
        )
      )
    ])
    error_message = "With connectivity_regions, every landing zone must set a supported region. Every corporate landing zone must also reference an existing network area."
  }

validation {
    condition = alltrue([
      for svc in values(var.landing_zone_namespace_services) :
      svc.namespace == null ? true : (
        length(svc.namespace) <= 63 &&
        can(regex("^[a-z0-9]([-a-z0-9]*[a-z0-9])?$", svc.namespace))
      )
    ])
    error_message = "If landing_zone_namespace_services.<key>.namespace is set, it must be a valid Kubernetes DNS-1123 label (<=63 chars, lowercase alphanumeric and '-', must start/end with alphanumeric)."
  }

validation {
    condition = alltrue([
      for svc in values(var.landing_zone_namespace_services) :
      svc.dns_subdomain == null ? true : (
        length(svc.dns_subdomain) <= 63 &&
        can(regex("^[a-z0-9]([-a-z0-9]*[a-z0-9])?$", svc.dns_subdomain))
      )
    ])
    error_message = "If landing_zone_namespace_services.<key>.dns_subdomain is set, it must be a valid DNS label (<=63 chars, lowercase alphanumeric and '-', must start/end with alphanumeric)."
  }

validation {
    condition = alltrue([
      for svc in values(var.landing_zone_namespace_services) :
      svc.kubernetes_access.service_account_name == null ? true : (
        length(svc.kubernetes_access.service_account_name) <= 63 &&
        can(regex("^[a-z0-9]([-a-z0-9]*[a-z0-9])?$", svc.kubernetes_access.service_account_name))
      )
    ])
    error_message = "If landing_zone_namespace_services.<key>.kubernetes_access.service_account_name is set, it must be a valid Kubernetes DNS-1123 label (<=63 chars, lowercase alphanumeric and '-', must start/end with alphanumeric)."
  }

validation {
    condition = alltrue([
      for svc in values(var.landing_zone_namespace_services) :
      contains(["audit", "soft", "strict"], lower(svc.secrets_enforcement.mode))
    ])
    error_message = "landing_zone_namespace_services.<key>.secrets_enforcement.mode must be one of: audit, soft, strict."
  }

validation {
    condition = alltrue([
      for svc in values(var.landing_zone_namespace_services) :
      svc.secrets_enforcement.break_glass.ttl_hours > 0
    ])
    error_message = "landing_zone_namespace_services.<key>.secrets_enforcement.break_glass.ttl_hours must be greater than 0."
  }

validation {
    condition = alltrue([
      for key in keys(var.landing_zone_namespace_services) : contains(keys(var.landing_zones), key)
    ])
    error_message = "Every key in landing_zone_namespace_services must also exist in landing_zones."
  }

validation {
    condition = (
      length(var.landing_zone_namespace_services) ==
      length(distinct([
        for key, svc in var.landing_zone_namespace_services :
        svc.namespace != null ? svc.namespace : trim(replace(lower(replace("${var.landing_zones[key].project_code}-${var.landing_zones[key].env}", "/[^a-zA-Z0-9-]/", "-")), "/-{2,}/", "-"), "-")
      ]))
    )
    error_message = "Each enabled namespace service must resolve to a unique namespace name."
  }

validation {
    condition = alltrue([
      for key, svc in var.landing_zone_namespace_services :
      length(svc.namespace != null ? svc.namespace : trim(replace(lower(replace("${var.landing_zones[key].project_code}-${var.landing_zones[key].env}", "/[^a-zA-Z0-9-]/", "-")), "/-{2,}/", "-"), "-")) > 0
    ])
    error_message = "Each enabled namespace service must resolve to a non-empty namespace name."
  }
